/**
 * Pruebas de `src/agents/save_result.mjs` — el tercer escritor del store de
 * agentes, portado de `kaupamex-docs: .claude/hooks/save-agent-result.mjs`.
 *
 * Qué viaja y qué no (DEC-04): viaja el MECANISMO —leer el transcript,
 * deduplicar el uso por `message.id`, ponderar el coste equivalente y componer
 * la entrada—. NO viaja el destino del log, que en la fuente se derivaba por
 * aritmetica de ruta (`dirname(dirname(here))`) y por tanto anclaba al
 * consumidor: aqui es parametro, y sin el se rehusa.
 *
 * El caso que DISCRIMINA es el 4: un agente cortado por maxTurns no deja
 * mensaje final PERO si deja uso. La fuente lo declara verbatim
 * (H-DOCS-106: 240 708 tokens, salida vacia); un puerto que sólo registrara
 * cuando hay texto escondería justo las ejecuciones que cuestan sin entregar.
 */
import { describe, expect, test } from 'bun:test'

/**
 * `save_result.mjs` no trae `.d.ts` propio (DEC-04: es guion `.mjs` que el
 * consumidor invoca con `node`). Se tipa aquí sólo la superficie que esta
 * prueba consume — no amplía el contrato real del módulo.
 */
declare module '../../src/agents/save_result.mjs' {
  export interface Usage {
    input: number
    cacheCreation: number
    cacheRead: number
    output: number
    turns: number
  }

  export function resolveLogFile(
    args?: Record<string, string>,
    env?: Record<string, string>,
  ): string | null
  export function usageFromLines(lines?: string[]): Usage
  export function lastAssistantText(lines?: string[]): string
  export function equivalentCost(usage: Usage): number
  export function harnessHeadline(usage: Usage): number
  export function shouldRecord(text: string, usage: Usage): boolean
  export function entryFor(params: {
    ts: string
    session: string
    transcript: string
    text: string
    usage: Usage
  }): string
  export const COST_KINDS: {
    equiv_tokens_fijos: string
    equiv_tokens_por_tier: string
    usd: string
    titular_harness: string
  }
}

import * as sr from '../../src/agents/save_result.mjs'

const linea = (id: string, texto: string, uso: Record<string, number>) =>
  JSON.stringify({
    type: 'assistant',
    message: { role: 'assistant', id, content: [{ type: 'text', text: texto }], usage: uso },
  })

const USO = {
  input_tokens: 10,
  cache_creation_input_tokens: 100,
  cache_read_input_tokens: 1000,
  output_tokens: 5,
}

describe('A. El destino del log es PARAMETRO, no `docs`', () => {
  test('sin destino declarado, rehusa en vez de inventarlo', () => {
    expect(sr.resolveLogFile({}, {})).toBeNull()
  })

  test('con --log-dir compone el archivo del registro', () => {
    const f = sr.resolveLogFile({ '--log-dir': '/x/agent-results' }, {})
    expect(f).toBe('/x/agent-results/registro-de-agentes.md')
  })

  test('la variable de entorno sirve de respaldo', () => {
    expect(sr.resolveLogFile({}, { AGENT_RESULTS_DIR: '/y' }))
      .toBe('/y/registro-de-agentes.md')
  })
})

describe('B. El uso se deduplica por message.id — last wins', () => {
  test('dos bloques del mismo turno cuentan UNA vez', () => {
    const uso = sr.usageFromLines([linea('m1', 'a', USO), linea('m1', 'b', USO)])
    expect(uso.turns).toBe(1)
    expect(uso.cacheRead).toBe(1000)
  })

  test('dos turnos distintos suman', () => {
    const uso = sr.usageFromLines([linea('m1', 'a', USO), linea('m2', 'b', USO)])
    expect(uso.turns).toBe(2)
    expect(uso.cacheRead).toBe(2000)
  })

  test('el ultimo texto no vacio gana', () => {
    expect(sr.lastAssistantText([linea('m1', 'primero', USO), linea('m2', 'ultimo', USO)]))
      .toBe('ultimo')
  })

  test('una linea que no parsea no revienta el recorrido', () => {
    const uso = sr.usageFromLines(['{no es json', '', linea('m1', 'a', USO)])
    expect(uso.turns).toBe(1)
  })
})

describe('C. El coste equivalente pondera, no suma en crudo', () => {
  test('los cuatro pesos de la fuente: 1 / 1.25 / 0.1 / 5', () => {
    // 10 + 1.25*100 + 0.1*1000 + 5*5 = 10 + 125 + 100 + 25 = 260
    expect(sr.equivalentCost(sr.usageFromLines([linea('m1', 'a', USO)]))).toBe(260)
  })

  test('sumar en crudo daria otra cifra — el control de que pondera', () => {
    const uso = sr.usageFromLines([linea('m1', 'a', USO)])
    const crudo = uso.input + uso.cacheCreation + uso.cacheRead + uso.output
    expect(sr.equivalentCost(uso)).not.toBe(crudo)
  })
})

describe('D. DISCRIMINA: un agente sin mensaje final PERO con uso SI se registra', () => {
  test('sin texto y con turnos, hay entrada', () => {
    const uso = { input: 0, cacheCreation: 0, cacheRead: 240708, output: 0, turns: 4 }
    expect(sr.shouldRecord('', uso)).toBe(true)
  })

  test('sin texto y sin turnos, no hay nada que registrar', () => {
    const vacio = { input: 0, cacheCreation: 0, cacheRead: 0, output: 0, turns: 0 }
    expect(sr.shouldRecord('', vacio)).toBe(false)
  })

  test('y la entrada lo dice en vez de dejar el cuerpo en blanco', () => {
    const uso = { input: 0, cacheCreation: 0, cacheRead: 240708, output: 0, turns: 4 }
    const e = sr.entryFor({ ts: '2026-09-06T21:00:00Z', session: 's1',
                            transcript: 't.jsonl', text: '', usage: uso })
    expect(e).toContain('sin mensaje final')
    expect(e).toContain('240,708')
  })
})

describe('E. Los CUATRO tipos de costo se declaran — no uno rotulado «el costo»', () => {
  test('el módulo nombra los cuatro y dice dónde vive cada uno', () => {
    expect(Object.keys(sr.COST_KINDS).sort())
      .toEqual(['equiv_tokens_fijos', 'equiv_tokens_por_tier', 'titular_harness', 'usd'])
    expect(sr.COST_KINDS.usd).toContain('model_catalog')
    // Los dos «equivalentes» NO son el mismo: uno fija la vara para poder
    // comparar filas, el otro la ajusta al tier real para acertar la ruta.
    expect(sr.COST_KINDS.equiv_tokens_fijos).not.toBe(sr.COST_KINDS.equiv_tokens_por_tier)
    expect(sr.COST_KINDS.equiv_tokens_por_tier).toContain('packages/agent/models.ts')
  })

  test('DISCRIMINA: el titular del harness y el ponderado NO son la misma cifra', () => {
    // El titular omite `cache_read`, que es el 98 % del consumo medido.
    const uso = sr.usageFromLines([JSON.stringify({
      type: 'assistant',
      message: { role: 'assistant', id: 'm1', content: [], usage: USO },
    })])
    expect(sr.harnessHeadline(uso)).toBe(10 + 100 + 5)     // 115, sin cache_read
    expect(sr.equivalentCost(uso)).toBe(260)               // con su peso 0.1
    expect(sr.equivalentCost(uso)).not.toBe(sr.harnessHeadline(uso))
  })

  test('cuanto más domina la caché, más se separan — que es por qué importa', () => {
    const conCache = { input: 0, cacheCreation: 0, cacheRead: 1_000_000, output: 0, turns: 1 }
    expect(sr.harnessHeadline(conCache)).toBe(0)            // el titular no ve nada
    expect(sr.equivalentCost(conCache)).toBe(100_000)       // el ponderado sí
  })

  test('el USD NO se calcula aquí: este módulo no lo expone', () => {
    // Su precio depende del modelo y del TTL; fabricarlo con los pesos de un
    // solo tier sería publicar una cifra que ningún modelo cobra.
    expect(Object.keys(sr).some((k) => /usd/i.test(k))).toBe(false)
  })
})

import { describe, expect, test } from 'bun:test'
import {
  stripHtmlComments,
  isMemoryFilePath,
  getLargeMemoryFiles,
} from '@thyrox/storage/claudemd.js'
import { buildEffectiveSystemPrompt } from '@thyrox/provider/systemPrompt.js'

// ─── CLAUDE.md Integration with System Prompt ─────────────────────────

describe('Context build: CLAUDE.md + system prompt integration', () => {
  test('buildEffectiveSystemPrompt passes through default prompt', () => {
    const result = buildEffectiveSystemPrompt({
      defaultSystemPrompt: ['You are Claude.'],
    })
    // Result is an array of strings (may be split differently)
    const joined = Array.from(result).join('')
    expect(joined).toBe('You are Claude.')
  })

  test('buildEffectiveSystemPrompt handles empty prompts', () => {
    const result = buildEffectiveSystemPrompt({
      defaultSystemPrompt: [''],
    })
    const joined = Array.from(result).join('')
    expect(joined).toBe('')
  })

  test('buildEffectiveSystemPrompt with overrideSystemPrompt replaces everything', () => {
    const result = buildEffectiveSystemPrompt({
      defaultSystemPrompt: ['Default'],
      overrideSystemPrompt: 'Override',
    })
    const joined = Array.from(result).join('')
    expect(joined).toBe('Override')
  })

  test('buildEffectiveSystemPrompt with customSystemPrompt replaces default', () => {
    const result = buildEffectiveSystemPrompt({
      defaultSystemPrompt: ['Default'],
      customSystemPrompt: 'Custom',
    })
    const joined = Array.from(result).join('')
    expect(joined).toBe('Custom')
  })

  test('buildEffectiveSystemPrompt with appendSystemPrompt includes both', () => {
    const result = buildEffectiveSystemPrompt({
      defaultSystemPrompt: ['Main prompt'],
      appendSystemPrompt: 'Appended',
    })
    const joined = Array.from(result).join('')
    expect(joined).toContain('Main prompt')
    expect(joined).toContain('Appended')
    // Appended should come after main
    expect(joined.indexOf('Main prompt')).toBeLessThan(
      joined.indexOf('Appended'),
    )
  })
})

// ─── CLAUDE.md Discovery with Real File System ───────────────────────

describe('Context build: CLAUDE.md file system integration', () => {
  test('strips HTML comments from CLAUDE.md content', () => {
    const input = '<!-- this is a comment -->Actual content'
    const { content, stripped } = stripHtmlComments(input)
    expect(content).toBe('Actual content')
    expect(stripped).toBe(true)
  })

  test('preserves code blocks when stripping HTML comments', () => {
    const input = '```\n<!-- not a real comment -->\n```\nReal text'
    const { content } = stripHtmlComments(input)
    expect(content).toContain('<!-- not a real comment -->')
    expect(content).toContain('Real text')
  })

  test('isMemoryFilePath correctly identifies CLAUDE.md paths', () => {
    expect(isMemoryFilePath('/project/CLAUDE.md')).toBe(true)
    expect(isMemoryFilePath('/project/CLAUDE.local.md')).toBe(true)
    expect(isMemoryFilePath('/project/.claude/rules/file.md')).toBe(true)
    expect(isMemoryFilePath('/project/README.md')).toBe(false)
    expect(isMemoryFilePath('/project/src/index.ts')).toBe(false)
  })
})

// ─── Large Memory File Filtering ──────────────────────────────────────

describe('Context build: large memory file filtering', () => {
  test('getLargeMemoryFiles returns empty for empty input', () => {
    expect(getLargeMemoryFiles([])).toEqual([])
  })

  test('getLargeMemoryFiles returns empty when all files are small', () => {
    const files = [
      { path: '/a/CLAUDE.md', content: 'small', type: 'Project' as const },
      { path: '/b/CLAUDE.md', content: 'also small', type: 'Project' as const },
    ]
    expect(getLargeMemoryFiles(files)).toEqual([])
  })
})

import { describe, expect, test } from 'bun:test'
import {
  getAllBaseTools,
  parseToolPreset,
  getTools,
} from '@thyrox/tool-registry/runtime'
import {
  findToolByName,
  getEmptyToolPermissionContext,
  buildTool,
} from '@thyrox/tool-registry/Tool.js'

// ─── Tool Registration & Discovery ──────────────────────────────────────

describe('Tool chain: registration and discovery', () => {
  test('getAllBaseTools returns a non-empty array of tools', () => {
    const tools = getAllBaseTools()
    expect(tools.length).toBeGreaterThan(0)
  })

  test('all base tools have required fields', () => {
    const tools = getAllBaseTools()
    for (const tool of tools) {
      expect(tool.name).toBeTruthy()
      expect(tool.description).toBeTruthy()
      expect(tool.inputSchema).toBeDefined()
      expect(typeof tool.call).toBe('function')
    }
  })

  test('findToolByName finds core tools from the full list', () => {
    const tools = getAllBaseTools()
    const bash = findToolByName(tools, 'Bash')
    expect(bash).toBeDefined()
    expect(bash!.name).toBe('Bash')

    const read = findToolByName(tools, 'Read')
    expect(read).toBeDefined()
    expect(read!.name).toBe('Read')

    const edit = findToolByName(tools, 'Edit')
    expect(edit).toBeDefined()
    expect(edit!.name).toBe('Edit')
  })

  test('findToolByName returns undefined for non-existent tool', () => {
    const tools = getAllBaseTools()
    expect(findToolByName(tools, 'NonExistentTool')).toBeUndefined()
  })

  test('findToolByName is case-sensitive (exact match only)', () => {
    const tools = getAllBaseTools()
    expect(findToolByName(tools, 'Bash')).toBeDefined()
    expect(findToolByName(tools, 'bash')).toBeUndefined()
  })

  test('findToolByName resolves via toolMatchesName', () => {
    const tools = getAllBaseTools()
    const agent = findToolByName(tools, 'Agent')
    expect(agent).toBeDefined()
    // Verify it can also find by checking name directly
    expect(tools.some(t => t.name === 'Agent')).toBe(true)
  })

  test('tool names are unique across the base tool list', () => {
    const tools = getAllBaseTools()
    const names = tools.map(t => t.name)
    expect(new Set(names).size).toBe(names.length)
  })
})

// ─── Tool Presets ──────────────────────────────────────────────────────

describe('Tool chain: presets', () => {
  test('parseToolPreset("default") returns "default" string', () => {
    // parseToolPreset returns a preset name string, not a tool array
    expect(parseToolPreset('default')).toBe('default')
  })

  test('parseToolPreset returns null for unknown preset', () => {
    expect(parseToolPreset('nonexistent')).toBeNull()
  })

  test('parseToolPreset is case-insensitive', () => {
    expect(parseToolPreset('DEFAULT')).toBe('default')
  })
})

// ─── getTools (with permission context) ────────────────────────────────

describe('Tool chain: getTools with context', () => {
  test('getTools returns tools (subset of base tools)', () => {
    const allTools = getAllBaseTools()
    const ctx = getEmptyToolPermissionContext()
    const tools = getTools(ctx)
    expect(tools.length).toBeGreaterThan(0)
    expect(tools.length).toBeLessThanOrEqual(allTools.length)
  })

  test('getTools results all have name and call function', () => {
    const ctx = getEmptyToolPermissionContext()
    const tools = getTools(ctx)
    for (const tool of tools) {
      expect(tool.name).toBeTruthy()
      expect(typeof tool.call).toBe('function')
    }
  })
})

// ─── buildTool + findToolByName end-to-end ─────────────────────────────

describe('Tool chain: buildTool + findToolByName', () => {
  test('a built tool can be found in a custom list', () => {
    const customTool = buildTool({
      name: 'TestTool',
      description: async () => 'A test tool',
      inputSchema: {
        type: 'object' as const,
        properties: { input: { type: 'string' } },
        required: ['input'],
      },
      call: async () => ({ data: { output: 'test' } }),
    })

    const found = findToolByName([customTool], 'TestTool')
    expect(found).toBe(customTool)
  })

  test('built tool defaults are correctly applied', () => {
    const tool = buildTool({
      name: 'MinimalTool',
      description: async () => 'Minimal',
      inputSchema: {
        type: 'object' as const,
        properties: {},
      },
      call: async () => ({ data: {} }),
    })

    expect(tool.isEnabled()).toBe(true)
    expect(tool.isConcurrencySafe()).toBe(false)
    expect(tool.isReadOnly()).toBe(false)
    expect(tool.isDestructive()).toBe(false)
  })
})

import { mock, describe, expect, test } from 'bun:test'
import type { TreeNode } from '@thyrox/repl/uiHelpers/treeify.js'

mock.module('figures', () => ({
  default: {
    lineUpDownRight: '├',
    lineUpRight: '└',
    lineVertical: '│',
  },
}))

mock.module('src/ink.js', () => ({
  color: (_colorKey: string, _themeName: string) => (text: string) => text,
}))

const { treeify } = await import('@thyrox/repl/uiHelpers/treeify.js')

describe('treeify', () => {
  test('renders flat tree with two keys', () => {
    const result = treeify({ a: 'value-a', b: 'value-b' })
    const lines = result.split('\n')
    expect(lines.length).toBe(2)
    expect(lines[0]).toContain('a')
    expect(lines[0]).toContain('value-a')
    expect(lines[1]).toContain('b')
    expect(lines[1]).toContain('value-b')
  })

  test('uses branch character for non-last items', () => {
    const result = treeify({ a: '1', b: '2' })
    // First item uses ├ (branch), last uses └ (lastBranch)
    expect(result).toContain('├')
    expect(result).toContain('└')
  })

  test('uses lastBranch for single item', () => {
    const result = treeify({ only: 'val' })
    expect(result).toContain('└')
    expect(result).not.toContain('├')
  })

  test('renders nested objects', () => {
    const result = treeify({ parent: { child: 'val' } })
    expect(result).toContain('parent')
    expect(result).toContain('child')
    expect(result).toContain('val')
  })

  test('renders arrays with length', () => {
    const result = treeify({ items: [1, 2, 3] })
    expect(result).toContain('items')
    expect(result).toContain('[Array(3)]')
  })

  test('detects circular references', () => {
    const obj: TreeNode = { name: 'root' }
    obj.self = obj
    const result = treeify(obj)
    expect(result).toContain('[Circular]')
  })

  test('returns (empty) for empty object', () => {
    const result = treeify({})
    expect(result).toBe('(empty)')
  })

  test('hideFunctions filters out function values', () => {
    const obj = { name: 'test', fn: () => {} }
    const result = treeify(obj, { hideFunctions: true })
    expect(result).toContain('name')
    expect(result).not.toContain('fn')
  })

  test('showValues false hides leaf values', () => {
    const obj = { name: 'test' }
    const result = treeify(obj, { showValues: false })
    expect(result).toContain('name')
    expect(result).not.toContain('test')
  })

  test('showValues true shows function as [Function]', () => {
    const obj = { fn: () => {} }
    const result = treeify(obj, { showValues: true })
    expect(result).toContain('[Function]')
  })

  test('deep nesting produces correct indentation', () => {
    const obj = { a: { b: { c: 'deep' } } }
    const result = treeify(obj)
    const lines = result.split('\n')
    expect(lines.length).toBe(3)
    // Each level adds indentation
    expect(lines[2]!.length).toBeGreaterThan(lines[1]!.length)
  })

  test('handles empty string key with string value', () => {
    const obj = { ' ': 'whitespace-key' }
    const result = treeify(obj)
    expect(result).toContain('whitespace-key')
  })

  test('handles mixed object and primitive values', () => {
    const obj = { name: 'test', nested: { inner: 'val' }, count: 5 }
    const result = treeify(obj)
    expect(result).toContain('name')
    expect(result).toContain('nested')
    expect(result).toContain('inner')
    expect(result).toContain('count')
  })
})
